"use client";

import * as React from "react";
import styles from "../styles/orbit-loader.module.css";

export interface OrbitLoaderProps {
  /** Loader diameter in pixels */
  size?: number;
  /** Outer orbit period in seconds (inner orbit runs at twice this, reversed) */
  duration?: number;
  /** Accent color for the core and leading satellite */
  color?: string;
  /** Accessible label announced by assistive technology */
  label?: string;
  /** Optional className merged onto the root */
  className?: string;
}

export function OrbitLoader({
  size = 72,
  duration = 1.4,
  color = "#38bdf8",
  label = "Loading",
  className = "",
}: OrbitLoaderProps) {
  const styleVars = {
    "--mf-ol-size": `${size}px`,
    "--mf-ol-duration": `${duration > 0 ? duration : 1.4}s`,
    "--mf-ol-color": color,
  } as React.CSSProperties;

  return (
    <div role="status" aria-label={label} style={styleVars} className={`${styles.root} ${className}`.trim()}>
      <span aria-hidden="true" className={styles.core} />
      <span aria-hidden="true" className={`${styles.ring} ${styles.outer}`}>
        <span className={`${styles.dot} ${styles.accentDot}`} />
      </span>
      <span aria-hidden="true" className={`${styles.ring} ${styles.inner}`}>
        <span className={styles.dot} />
      </span>
    </div>
  );
}

.root {
  position: relative;
  display: inline-block;
  flex-shrink: 0;
  width: var(--mf-ol-size, 72px);
  height: var(--mf-ol-size, 72px);
}

.core {
  position: absolute;
  inset: 38%;
  border-radius: 50%;
  background-color: var(--mf-ol-color, var(--mf-accent, #38bdf8));
  box-shadow: 0 0 calc(var(--mf-ol-size, 72px) * 0.18) var(--mf-ol-color, var(--mf-accent, #38bdf8));
  animation: mfOrbitBreathe calc(var(--mf-ol-duration, 1.4s) * 2) ease-in-out infinite;
}

.ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid var(--mf-border, #2e2e38);
  animation: mfOrbitSpin var(--mf-ol-duration, 1.4s) linear infinite;
  will-change: transform;
}

.outer {
  inset: 0;
}

.inner {
  inset: calc(var(--mf-ol-size, 72px) * 0.15);
  animation-duration: calc(var(--mf-ol-duration, 1.4s) * 2);
  animation-direction: reverse;
}

.dot {
  position: absolute;
  top: -4px;
  left: 50%;
  width: 8px;
  height: 8px;
  margin-left: -4px;
  border-radius: 50%;
  background-color: var(--mf-fg, #f4f4f6);
}

.accentDot {
  background-color: var(--mf-ol-color, var(--mf-accent, #38bdf8));
  box-shadow: 0 0 8px var(--mf-ol-color, var(--mf-accent, #38bdf8));
}

@keyframes mfOrbitSpin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes mfOrbitBreathe {
  0%,
  100% {
    transform: scale(1);
    opacity: 1;
  }
  50% {
    transform: scale(0.82);
    opacity: 0.75;
  }
}

@media (prefers-reduced-motion: reduce) {
  .core,
  .ring {
    animation: none;
  }

  .inner {
    transform: rotate(140deg);
  }
}

