"use client";

import { motion } from "motion/react";

export function OrbitLoaderTailwind({ size = 72, duration = 1.4 }) {
  return (
    <div role="status" aria-label="Loading" className="relative" style={{ width: size, height: size }}>
      <span className="absolute inset-[38%] rounded-full bg-sky-400 shadow-[0_0_14px] shadow-sky-400" />
      {[0, 1].map((i) => (
        <motion.div
          key={i}
          aria-hidden
          className="absolute rounded-full border border-zinc-800"
          style={{ inset: i * size * 0.15 }}
          animate={{ rotate: i ? -360 : 360 }}
          transition={{ duration: duration * (i + 1), repeat: Infinity, ease: "linear" }}
        >
          <span className={`absolute -top-1 left-1/2 h-2 w-2 -translate-x-1/2 rounded-full ${i ? "bg-zinc-100" : "bg-sky-400"}`} />
        </motion.div>
      ))}
    </div>
  );
}
